select * from Customers

SELECT COUNT(*) FROM Customers;

SELECT MIN(CustomerID) AS MinID, MAX(CustomerID) AS MaxID, COUNT(*) AS TotalRows FROM Customers;

SELECT MIN(EmployeeID) AS MinID, MAX(EmployeeID) AS MaxID, COUNT(*) AS TotalRows FROM Employees;


SELECT 'CustomerAddress' AS TableName, COUNT(*) AS Rows FROM CustomerAddress
